class PresentationFormat(Enum):
    by_function = "by_function"
    by_nature = "by_nature"
    unknown = "unknown"


class PresentationFormatDetectionNote(BaseModel):
    scanned_by_function_tags: list[str]
    scanned_by_nature_tags: list[str]
    matched: list[str]


class ReportingNotes(BaseModel):
    # SDK-24 hand-correction: typed as Literal (not PresentationFormat enum)
    # per SDK-24 Section 1. Consumer code reads `.presentation_format` as a
    # string; enum access would require `.value` and change call sites.
    presentation_format: Annotated[
        Literal["by_function", "by_nature", "unknown"],
        Field(title="Presentation Format"),
    ]
    """
    Income-statement presentation format. 'by_function' groups expenses by function (cost of sales, distribution, admin) — most US-GAAP filers and a majority of IFRS filers. 'by_nature' groups by nature (raw materials, employee benefits, depreciation) — many European industrials and manufacturers, where cost_of_revenue, gross_profit, and selling_general_admin are NULL by design (not a parser bug). 'unknown' means detection could not classify the filing; income-statement subtotals should be treated as unreliable on these filings, though top-level totals are still populated where possible.
    """
    ifrs_18_applied: Annotated[bool, Field(title="Ifrs 18 Applied")]
    """
    True if the filing applies IFRS 18 (effective for annual periods beginning on or after 2027-01-01). Always false for US-GAAP filings and for any fiscal year before 2027. When true, operating-income semantics and certain subtotal categorisations follow IFRS 18's mandated structure rather than the pre-IFRS-18 election regime.
    """
    taxonomy_changed_in_amendment: Annotated[bool | None, Field(title="Taxonomy Changed In Amendment")] = None
    """
    Conditional: present only when an amendment changes the filing's taxonomy (us-gaap vs ifrs-full) versus the original filing. Absent — not null — when no mismatch. Signals that cross-period comparisons within this CIK must account for the mid-series taxonomy switch.
    """
    currency_changed_in_amendment: Annotated[bool | None, Field(title="Currency Changed In Amendment")] = None
    """
    Conditional: present only when an amendment changes the filing's presentation currency versus the original. Absent — not null — when no mismatch. Rare (typically post-merger); flag is here so downstream consumers can handle the cross-currency discontinuity explicitly.
    """
    taxonomy_detection_ambiguous: Annotated[bool | None, Field(title="Taxonomy Detection Ambiguous")] = None
    """
    Conditional: present only when the ratio of minority-to-majority taxonomy-tag counts on the filing is >= 10%. Majority still wins and the filing still parses normally; the flag is ops-visible and signals the taxonomy attribution is less confident than usual. Absent — not null — when detection is unambiguous.
    """
    currency_detection_ambiguous: Annotated[bool | None, Field(title="Currency Detection Ambiguous")] = None
    """
    Conditional: present only when multiple ISO-4217 codes appear on the filing's monetary facts AND the minority currency's share exceeds 20% of total monetary facts. Majority still wins; flag signals a blended-currency filing that may warrant manual review. Absent — not null — when detection is unambiguous.
    """
    presentation_format_detection_note: Annotated[
        PresentationFormatDetectionNote | None,
        Field(title="PresentationFormatDetectionNote"),
    ] = None
    """
    Conditional: forensic provenance of the presentation-format detection. Present ONLY when presentation_format='unknown'. Lists the by-function and by-nature indicator tags scanned on the filing, plus any that matched. Diagnostic surface for support/ops investigations — not intended for customer code paths. Absent (not null) on filings where detection succeeded.
    """


