class RatioResponse(BaseModel):
    company: CompanySummary
    """
    Company identification details.
    """
    period: Annotated[Period, Field(title="Period")]
    """
    Reporting period type.
    """
    fiscal_year: Annotated[int, Field(title="Fiscal Year")]
    """
    Fiscal year of the reported ratios.
    """
    fiscal_quarter: Annotated[int | None, Field(title="Fiscal Quarter")] = None
    """
    Fiscal quarter (1-4) for quarterly ratios, null for annual.
    """
    taxonomy: Annotated[Taxonomy | None, Field(title="Taxonomy")] = None
    """
    XBRL taxonomy of the underlying financial statement. 'us-gaap' for existing data; IFRS-full parsing lands with IFRS-04. Null when no underlying statement row is linked.
    """
    currency: Annotated[str | None, Field(title="Currency")] = None
    """
    ISO 4217 presentation currency of the underlying financial statement. Null when no underlying statement row is linked.
    """
    ratios: RatioValues
    """
    Computed financial ratios for this period.
    """
    metadata: RatioMetadata
    """
    Source metadata for the ratio computation.
    """


